package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class AudioNamingTest {
 static int checks;static void ok(boolean b,String s){if(!b)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}
 public static void main(String[] args)throws Exception{
  ok(AudioTitles.file("Estudos","Introdução",0,1).equals("Estudos — Introdução — 0001.wav"),"book and chapter precede track number");ok(AudioTitles.file("Estudos","Introdução",0,2).endsWith("0001-02.wav"),"split chapter keeps original chapter and part numbers");ok(AudioTitles.file("Livro","Introdução",0,1,true).endsWith("0001-01.wav")&&AudioTitles.file("Livro","Introdução",0,1,true).compareTo(AudioTitles.file("Livro","Introdução",0,2,true))<0,"split pieces keep first part before second in filename order");ok(AudioTitles.file("Livro","Livro",9,1).equals("Livro — 0010.wav"),"duplicate title is shown once");ok(AudioTitles.file("","",0,1).equals("Narração — 0001.wav"),"missing metadata has safe numbered fallback");ok(!AudioTitles.file("../Livro:/", "Capítulo?*",1,1).contains("/"),"unsafe filename delimiters removed");
  String longTitle=String.join("",Collections.nCopies(150,"📚É")),name=AudioTitles.file(longTitle,longTitle+"fim",9999,2);ok(name.length()<120&&name.getBytes(StandardCharsets.UTF_8).length<=220&&name.endsWith("10000-02.wav"),"long Unicode titles preserve filename limits, number and extension");ok(!Character.isHighSurrogate(name.charAt(name.length()-1)),"Unicode title truncation preserves code points");
  ok(AudioTitles.firstHeading("# Energia e movimento\n\nTexto.").equals("Energia e movimento"),"Markdown heading used as subtitle");ok(AudioTitles.firstHeading("Uma frase completa.\n\nMais texto").isEmpty(),"ordinary sentence is not presented as a heading");ok(AudioTitles.generic("Capítulo 12")&&AudioTitles.generic("Documento")&&!AudioTitles.generic("Vida e saúde"),"generated generic chapter labels give way to actual headings");ok(AudioTitles.book("Título interno","arquivo.epub","Título escolhido").equals("Título escolhido"),"edited library title takes precedence");ok(AudioTitles.book("Título interno","arquivo.epub","arquivo.epub").equals("Título interno"),"imported filename does not obscure book metadata");
  ok(BookArchive.heading(BookArchive.xml("<html><body><h2>Subtítulo do livro</h2><p>Texto.</p></body></html>".getBytes(StandardCharsets.UTF_8)),true).equals("Subtítulo do livro"),"EPUB subtitle extracted from heading structure");ok(BookArchive.heading(BookArchive.xml("<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:pPr><w:pStyle w:val='Heading1'/></w:pPr><w:r><w:t>Introdução DOCX</w:t></w:r></w:p></w:body></w:document>".getBytes(StandardCharsets.UTF_8)),false).equals("Introdução DOCX"),"DOCX heading style supplies audio subtitle");
  Path directory=Files.createTempDirectory("wav-titles-");File input=directory.resolve("input.wav").toFile(),target=directory.resolve("titled.wav").toFile();byte[] samples={1,0,2,0,3,0};WaveJoinerTest.wav(input,24000,1,16,samples);try(WaveJoiner joiner=new WaveJoiner(target)){joiner.append(input,()->false);joiner.finish(()->false,new WavInfo("Estudos — Introdução — 0001","Estudos de Ciências","Ana Silva",1));}WaveJoiner.Format format=WaveJoiner.inspect(target);byte[] bytes=Files.readAllBytes(target.toPath());ok(Arrays.equals(samples,Arrays.copyOfRange(bytes,(int)format.offset,(int)(format.offset+format.length))),"metadata leaves every PCM sample unchanged");ok(format.rate==24000&&format.bits==16&&format.channels==1,"tags do not change audio format");Map<String,String> tags=tags(target);ok(tags.get("INAM").equals("Estudos — Introdução — 0001")&&tags.get("IPRD").equals("Estudos de Ciências"),"RIFF tags carry track title and book");ok(tags.get("IART").equals("Ana Silva")&&tags.get("ITRK").equals("1"),"author and track number are embedded");ok(tags.get("ISFT").contains("Haidoy Carlos Mautempo"),"software credit retains requested signature");
  try(RandomAccessFile in=new RandomAccessFile(target,"r")){in.seek(4);ok(Integer.toUnsignedLong(Integer.reverseBytes(in.readInt()))+8==in.length(),"RIFF size includes appended metadata");}
  File odd=directory.resolve("odd.wav").toFile(),oddOut=directory.resolve("odd-titled.wav").toFile();WaveJoinerTest.wav(odd,16000,1,8,new byte[]{1,2,3});try(WaveJoiner joiner=new WaveJoiner(oddOut)){joiner.append(odd,()->false);joiner.finish(()->false,new WavInfo("Índice","Livro","",7));}ok(WaveJoiner.inspect(oddOut).length==3&&tags(oddOut).get("INAM").equals("Índice"),"odd PCM byte count stays aligned before tags");
  String evidence=System.getProperty("seeky.audio.fixture","");if(!evidence.isEmpty())Files.copy(target.toPath(),Paths.get(evidence),StandardCopyOption.REPLACE_EXISTING);
  System.out.println("PASS "+checks+" audio naming and metadata checks");
 }
 static Map<String,String> tags(File file)throws IOException{Map<String,String> result=new HashMap<>();try(RandomAccessFile in=new RandomAccessFile(file,"r")){in.seek(12);while(in.getFilePointer()+8<=in.length()){int tag=in.readInt();long length=Integer.toUnsignedLong(Integer.reverseBytes(in.readInt())),next=in.getFilePointer()+length;if(next>in.length())throw new IOException("Bad chunk");if(tag==0x4c495354&&length>=4&&in.readInt()==0x494e464f){while(in.getFilePointer()+8<=next){byte[] key=new byte[4];in.readFully(key);int count=Integer.reverseBytes(in.readInt());if(count<1||count>2048||in.getFilePointer()+count>next)throw new IOException("Bad metadata");byte[] value=new byte[count];in.readFully(value);result.put(new String(key,"US-ASCII"),new String(value,0,count-1,"UTF-8"));if((count&1)!=0)in.skipBytes(1);}}in.seek(next+(length&1));}}return result;}
}
